<?php

namespace App\Http\Controllers\Api\V1;

use App\Http\Controllers\Controller;
use App\Models\User;
use Illuminate\Auth\Events\Verified;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;

/**
 * Confirms a signed email-verification link, then bounces the user back to the
 * frontend. The link is generated by Laravel's VerifyEmail notification.
 */
class EmailVerificationController extends Controller
{
    public function __invoke(Request $request, int $id, string $hash): RedirectResponse
    {
        $user = User::findOrFail($id);
        $frontend = rtrim(env('FRONTEND_URL', 'http://localhost:3000'), '/');

        if (! hash_equals(sha1($user->getEmailForVerification()), $hash)) {
            return redirect("{$frontend}/verify-email?status=invalid");
        }

        if (! $user->hasVerifiedEmail()) {
            $user->markEmailAsVerified();
            event(new Verified($user));
        }

        return redirect("{$frontend}/verify-email?status=verified");
    }
}
